-- ============================================================================
-- Part 2: integrity rules Prisma cannot express
-- ============================================================================

-- users ---------------------------------------------------------------------
ALTER TABLE "users"
    ADD CONSTRAINT "users_phone_e164" CHECK (phone ~ '^\+[1-9][0-9]{6,14}$');

-- auth_identities -------------------------------------------------------------
ALTER TABLE "auth_identities"
    ADD CONSTRAINT "auth_identities_provider_format" CHECK (provider ~ '^[a-z][a-z0-9_-]{1,29}$'),
    ADD CONSTRAINT "auth_identities_subject_not_blank" CHECK (length(btrim(subject)) > 0);

-- drivers ---------------------------------------------------------------------
ALTER TABLE "drivers"
    ADD CONSTRAINT "drivers_approved_requires_timestamp"
        CHECK (approval_status <> 'APPROVED' OR approved_at IS NOT NULL);

-- driver_wallets (PW 1.1) -----------------------------------------------------
ALTER TABLE "driver_wallets"
    ADD CONSTRAINT "wallet_balance_nonnegative" CHECK (balance_paise >= 0),
    ADD CONSTRAINT "wallet_version_nonnegative" CHECK (version >= 0);

-- driver_wallet_transactions (PW 1.2) -----------------------------------------
ALTER TABLE "driver_wallet_transactions"
    ADD CONSTRAINT "wallet_tx_amount_positive" CHECK (amount_paise > 0),
    ADD CONSTRAINT "wallet_tx_balance_nonnegative" CHECK (balance_after_paise >= 0),
    ADD CONSTRAINT "wallet_tx_wallet_version_positive" CHECK (wallet_version > 0),
    ADD CONSTRAINT "wallet_tx_idempotency_key_not_blank" CHECK (length(btrim(idempotency_key)) > 0),
    ADD CONSTRAINT "wallet_tx_reference_not_blank"
        CHECK (length(btrim(reference_type)) > 0 AND length(btrim(reference_id)) > 0),
    -- A top-up can only add money; a cash-ride fee can only remove it.
    ADD CONSTRAINT "wallet_tx_type_direction"
        CHECK ((type <> 'TOPUP' OR direction = 'CREDIT') AND (type <> 'CASH_RIDE_FEE' OR direction = 'DEBIT')),
    -- Every top-up credit must trace back to a provider order and payment (reconciliation).
    ADD CONSTRAINT "wallet_tx_topup_provider_refs"
        CHECK (type <> 'TOPUP' OR (provider IS NOT NULL AND provider_order_id IS NOT NULL AND provider_payment_id IS NOT NULL)),
    -- PW 8: manual adjustments require the acting admin and a reason.
    ADD CONSTRAINT "wallet_tx_adjustment_audit"
        CHECK (type <> 'ADJUSTMENT' OR (performed_by_user_id IS NOT NULL AND reason IS NOT NULL AND length(btrim(reason)) > 0)),
    ADD CONSTRAINT "wallet_tx_metadata_object" CHECK (jsonb_typeof(metadata) = 'object');

-- PW 9.1: the ledger is append-only. Corrections are compensating entries, never edits.
CREATE OR REPLACE FUNCTION prevent_wallet_ledger_mutation()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'Wallet ledger is append-only; use a compensating transaction'
        USING ERRCODE = 'restrict_violation';
END;
$$;

CREATE TRIGGER trg_wallet_ledger_immutable
BEFORE UPDATE OR DELETE ON "driver_wallet_transactions"
FOR EACH ROW
EXECUTE FUNCTION prevent_wallet_ledger_mutation();

-- Row triggers do not fire on TRUNCATE, so block it separately.
CREATE TRIGGER trg_wallet_ledger_no_truncate
BEFORE TRUNCATE ON "driver_wallet_transactions"
FOR EACH STATEMENT
EXECUTE FUNCTION prevent_wallet_ledger_mutation();

-- payments (PW 1.3) -----------------------------------------------------------
ALTER TABLE "payments"
    ADD CONSTRAINT "payments_purpose_valid" CHECK (purpose IN ('BOOKING', 'DRIVER_WALLET_TOPUP')),
    ADD CONSTRAINT "payments_amount_positive" CHECK (amount_paise > 0),
    ADD CONSTRAINT "payments_currency_inr" CHECK (currency = 'INR'),
    ADD CONSTRAINT "payments_booking_required" CHECK (purpose <> 'BOOKING' OR booking_id IS NOT NULL),
    ADD CONSTRAINT "payments_topup_has_no_booking" CHECK (purpose <> 'DRIVER_WALLET_TOPUP' OR booking_id IS NULL),
    -- A settled payment must reference both the provider order and the provider payment.
    ADD CONSTRAINT "payments_settled_has_provider_refs"
        CHECK (status NOT IN ('PAID', 'REFUND_PENDING', 'REFUNDED')
               OR (razorpay_order_id IS NOT NULL AND razorpay_payment_id IS NOT NULL)),
    ADD CONSTRAINT "payments_idempotency_key_not_blank" CHECK (length(btrim(idempotency_key)) > 0);

-- payment_events (PW 1.4) -----------------------------------------------------
ALTER TABLE "payment_events"
    -- Unverified webhook requests are rejected before storage, so a forged request can never
    -- reserve an event id and block the genuine event.
    ADD CONSTRAINT "payment_events_only_verified" CHECK (signature_valid),
    ADD CONSTRAINT "payment_events_attempts_nonnegative" CHECK (attempts >= 0);

-- Documentation for anyone reading the database directly ---------------------
COMMENT ON TABLE "driver_wallets" IS 'One wallet per driver (PW 1.1). balance_paise is a cached balance; driver_wallet_transactions is the audit trail.';
COMMENT ON COLUMN "driver_wallets"."balance_paise" IS 'Balance in paise (100 paise = 1 INR). Must always equal the sum of POSTED ledger entries; see reconciliation queries.';
COMMENT ON TABLE "driver_wallet_transactions" IS 'Append-only wallet ledger (PW 1.2). UPDATE, DELETE and TRUNCATE are blocked by triggers.';
COMMENT ON COLUMN "driver_wallet_transactions"."amount_paise" IS 'Always positive. direction decides whether it is a credit or a debit.';
COMMENT ON COLUMN "driver_wallet_transactions"."wallet_version" IS 'driver_wallets.version after this entry. Unique per wallet: entries form a gap-free chain 1, 2, 3, ...';
COMMENT ON TABLE "payments" IS 'Razorpay payment records (PW 1.3). One row per Razorpay order.';
COMMENT ON COLUMN "payments"."amount_paise" IS 'Server-determined amount in paise. Never accepted from the client as a final amount.';
COMMENT ON TABLE "payment_events" IS 'Signature-verified Razorpay webhook events (PW 1.4). event_id is the idempotency guard.';
COMMENT ON COLUMN "payment_events"."payload" IS 'Raw provider payload. Contains customer contact data; access must be restricted.';
